var expireFresh = (grid, minutes, toBeContinued = false) => {
  const [rows, cols] = [grid.length, grid[0].length];
  for (let row = 0; row < rows; row++) {
    /* Time O(ROWS) */
    for (let col = 0; col < cols; col++) {
