        if (!isFresh) continue;
        grid[_row][_col] = minutes + 1;
        toBeContinued = true;
      }
    }
  }
  return toBeContinued;
};
var getNeighbors = (row, rows, col, cols) => [[0, 1], [0, -1], [1, 0], [-1, 0]].map(([_row, _col]) => [row + _row, col + _col]).filter(([_row, _col]) => 0 <= _row && _row < rows && 0 <= _col && _col < cols);
const hasFresh = grid => {
  for (const row of grid) {
    /* Time O(ROWS) */
    for (const cell of row) {
      /* Time O(COLS) */
      const isFresh = cell === 1;
      if (isFresh) return true;
    }
  }
  return false;
